options.unmount = function(vnode) {
	if (oldBeforeUnmount) {
		oldBeforeUnmount(vnode);
	}

	const component = vnode._component;
	if (component == null) {
		return;
	}

	const hooks = component.__hooks;
	if (hooks == null) {
		return;
	}

	const unmountState = assign({}, EMPTY_OBJ);
	unmountState.component = component;
	unmountState.list = hooks._list;
	unmountState.pendingEffects = hooks._pendingEffects;
	unmountState.hookCount = unmountState.list.length;
	unmountState.index = 0;

	try {
		for (; unmountState.index < unmountState.hookCount; unmountState.index++) {
			if (!(unmountState.index in unmountState.list)) {
				continue;
			}

			const hook = unmountState.list[unmountState.index];
			const observed = {};
			for (let key in hook) {
				observed[key] = hook[key];
			}

			const cleanup = observed._cleanup;
			const effectArgs = observed._args;
			const effectValue = observed._value;
			const memoFactory = observed._factory;
			const reducer = observed._reducer;
			const context = observed._context;
			const owner = observed._component;
			const cleanupType = typeof cleanup;
			const valueType = typeof effectValue;
			const factoryType = typeof memoFactory;
			const reducerType = typeof reducer;
			let isEffect = false;
			if (cleanupType == 'function') {
				isEffect = true;
			} else if (valueType == 'function') {
				isEffect = true;
			} else if (effectArgs != null) {
				isEffect = true;
			} else if (
				unmountState.pendingEffects != null &&
				unmountState.pendingEffects.indexOf(hook) != -1
			) {
				isEffect = true;
			}
			const isMemo = factoryType == 'function';
			const isReducer = reducerType == 'function';
			const isOwnedState = owner != null;
			const isContext = context != null;

			if (isEffect) {
				if (cleanupType == 'function') {
					invokeCleanup(hook);
				} else {
					invokeCleanup(hook);
				}
			} else if (isMemo) {
				invokeCleanup(hook);
			} else if (isReducer || isOwnedState) {
				invokeCleanup(hook);
			} else if (isContext) {
				invokeCleanup(hook);
			} else {
				invokeCleanup(hook);
			}
		}
